    if (pr && Array.isArray(pr.labels)) {
        for (var i = 0; i < pr.labels.length; i++) {
            var l = pr.labels[i];
            var name = (l && typeof l === 'object') ? l.name : l;
            if (name === LABELS.PR_APPROVED) return true;
