        if (baseMatch && baseMatch[1]) baseBranch = baseMatch[1].trim();
    } catch (e) {}

    var currentBranch = cleanCommandOutput(cmd('git branch --show-current') || '');
    console.log('Current branch:', currentBranch, '| Expected:', expectedBranch);

    var branchName = currentBranch;
    if (expectedBranch && currentBranch !== expectedBranch) {
        console.warn('⚠️ Branch mismatch — forcing checkout to expected branch:', expectedBranch);
        try {
            cmd('git checkout ' + expectedBranch);
            branchName = expectedBranch;
            console.log('✅ Switched to expected branch:', branchName);
        } catch (e) {
            console…

/**
 * SCM (Source Control Management) abstraction layer.
 *
 * Factory: createScm(config) -> provider
 * Default provider: 'github'
 *
 * Configure globally via .dmtools/config.js:
 *   module.exports = {
 *     scm: { provider: 'ado' }, // 'github' | 'gitlab' | 'ado'
 *     repository: { owner: 'MyOrg', repo: 'my-repo' }
 *   }
 *
 * Per-agent override via JSON customParams:
 *   { "customParams": { "scmProvider": "gitlab", "targetRepository": { "owner": "MyOrg", "repo": "my-repo" } } }
 */

function _parseJson(raw) {
    if (typeof raw === 'string') {
        try { return JSON.parse(raw); } catch (e) { return raw; }
    }
    return raw;
}

function _toArray(raw) {
    var parsed = _parseJson(raw);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && parsed.value) return parsed.value;
    if (parsed && parsed.workflow_runs) return parsed.workflow_runs;
    if (parsed && parsed.runs) return parsed.runs;
    return parsed ? [parsed] : [];
}

function _readFileMaybe(path) {
    try {
        var raw = file_read({ path: path });
        if (raw && raw.trim()) return raw;
    } catch (e) {
        try {
            raw = file_read(path);
            if (raw && raw.trim()) return raw;
        } catch (ignored) {}
    }
    return null;
}

function _cleanCommandOutput(output) {
    if (!output) return '';
    return output.split('\n').filter(function(line) {
        return line.indexOf('Script started') === -1 &&
               line.indexOf('Script done') === -1 &&
               line.indexOf('COMMAND=') === -1 &&
               line.indexOf('COMMAND_EXIT_CODE=') === -1;
    }).join('\n').trim();
}

function _looksLikeJavaObjectString(value) {
    return typeof value === 'string' && /^[A-Za-z0-9_.$]+@[0-9a-f]+$/.test(value.trim());
}

function _isUsableDiff(value) {
    return typeof value === 'string' && value.indexOf('diff --git') !== -1 && !_looksLikeJavaObjectString(value);
}

function _extractDiffFromToolResult(raw) {
    if (typeof raw !== 'string') {
        return raw;
    }
    // Some DMTools versions wrap the diff in a JSON envelope like {"result": "diff ..."}
    // or serialize an IBody lambda as {"arg$1": "diff ..."}. Unwrap those first.
    var trimmed = raw.trim();
    if (trimmed.charAt(0) === '{' || trimmed.charAt(0) === '[') {
        try {
            var parsed = JSON.parse(raw);
            var candidates = [parsed.result, parsed['arg$1'], parsed.body, parsed.diff];
            for (var i = 0; i < candidates.length; i++) {
                var candidate = candidates[i];
                if (typeof candidate === 'string' && _isUsableDiff(candidate)) {
                    return candidate;
                }
            }
        } catch (e) {
            // Not valid JSON — fall through to raw diff check
        }
    }
    if (_isUsableDiff(raw)) {
        return raw;
    }
    return raw;
}

function _runGitDiff(baseRef, headRef, workingDir) {
    var variants = [
        'git diff ' + baseRef + '...' + headRef,
        'git diff origin/' + baseRef + '...' + headRef,
        'git diff origin/' + baseRef + '...origin/' + headRef
    ];
    var cmdOpts = workingDir ? { workingDirectory: workingDir } : {};
    for (var i = 0; i < variants.length; i++) {
        try {
            var raw = cli_execute_command(Object.assign({}, cmdOpts, { command: variants[i] })) || '';
            var cleaned = _cleanCommandOutput(raw);
            if (_isUsableDiff(cleaned)) {
                console.log('Generated local git diff using: ' + variants[i] + ' (' + cleaned.length + ' chars)');
                return cleaned;
            }
        } catch (e) {
            console.warn('Git diff variant failed (' + variants[i] + '):', e.message || e);
        }
    }
    return '';
}

/**
 * Normalize a legacy GitHub commit-status entry (the classic pre-Checks-API
 * `/commits/{sha}/statuses` endpoint, still used by external CI systems such as Jenkins
 * that report build results via the Status API instead of GitHub Check Runs) into the same
 * shape detectFailedChecks() expects from github_get_commit_check_runs: { name, conclusion, details_url }.
 */
function _normalizeGithubCommitStatus(status) {
    var s = String((status && status.state) || '').toLowerCase();
    var conclusion = (s === 'failure' || s === 'error') ? 'failure'
        : (s === 'success') ? 'success'
        : s; // pending passes through and is filtered out by detectFailedChecks
    return {
        name: (status && status.context) || 'unknown',
        conclusion: conclusion,
        details_url: (status && status.target_url) || null
    };
}

/**
 * Fetch legacy commit statuses for a GitHub commit. No dedicated MCP tool exists for the
 * classic Status API, so this shells out via `gh api` (same established pattern as
 * updateBranch() below) and keeps only the most recent report per context — GitHub returns
 * statuses newest-first, so the first occurrence per context wins.
 */
function _getLegacyGithubCommitStatuses(workspace, repository, sha) {
    try {
        var raw = cli_execute_command({
            command: 'gh api repos/' + workspace + '/' + repository + '/commits/' + sha + '/statuses --paginate'
        }) || '';
        var cleaned = _cleanCommandOutput(raw);
        if (!cleaned) return [];
        var statuses = JSON.parse(cleaned);
        if (!Array.isArray(statuses)) return [];
        var seenContexts = {};
        var latest = [];
        for (var i = 0; i < statuses.length; i++) {
            var ctx = statuses[i].context || 'unknown';
            if (seenContexts[ctx]) continue;
            seenContexts[ctx] = true;
            latest.push(statuses[i]);
        }
        return latest;
    } catch (e) {
        console.warn('SCM GitHub: failed to fetch legacy commit statuses for', sha, ':', e.message || e);
        return [];
    }
}

/**
 * Unwrap the raw github_get_commit_check_runs() response into a plain array, tolerating the
 * various envelopes DMTools builds have used ({"result": ...}, {"check_runs": [...]}, a raw
 * array, or a single object).
 */
function _unwrapGithubCheckRuns(raw) {
    var parsed = _parseJson(raw);
    if (parsed && typeof parsed.result !== 'undefined') {
        parsed = _parseJson(parsed.result);
    }
    if (Array.isArray(parsed)) return parsed;
    if (parsed && Array.isArray(parsed.check_runs)) return parsed.check_runs;
    return parsed ? [parsed] : [];
}

function _createGithubProvider(workspace, repository) {
    return {
        listPrs: function(state) {
            return github_list_prs({ workspace: workspace, repository: repository, state: state });
        },
        getPr: function(prId) {
            return github_get_pr({ workspace: workspace, repository: repository, pullRequestId: String(prId) });
        },
        getPrComments: function(prId) {
            return github_get_pr_comments({ workspace: workspace, repository: repository, pullRequestId: String(prId) });
        },
        // Raw unified diff text via the PR API — works even after the PR is merged and
        // its head branch deleted (unlike a local `git diff <head>..<base>`).
        // Requires IS_READ_PULL_REQUEST_DIFF to be enabled; returns null on failure so
        // callers can fall back gracefully.
        getDiffText: function(prId) {
            try {
                return github_get_pr_diff_text({ workspace: workspace, repository: repository, pullRequestID: String(prId) });
            } catch (e) {
                console.warn('getDiffText (github) failed:', e && e.toString ? e.toString() : String(e));
                return null;
            }
        },
        addComment: function(prId, text) {
            return github_add_pr_comment({ workspace: workspace, repository: repository, pullRequestId: String(prId), text: text });
        },
        replyToThread: function(prId, thread, text) {
            if (thread.rootCommentId) {
                return github_reply_to_pr_thread({
                    workspace: workspace, repository: repository,
                    pullRequestId: String(prId), inReplyToId: String(thread.rootCommentId), text: text
                });
            }
            return github_add_pr_comm…

/**
 * Pre-CLI Rework Setup Action (preCliJSAction for pr_rework agent)
 * 1. Finds the existing PR for the ticket
 * 2. Checks out the PR branch
 * 3. Merges origin/{baseBranch} into the PR branch (auto-update, before setup commands run —
 *    see the comment above the detectMergeConflicts() call for why the order matters)
 * 4. Runs project-specific setup commands (build/verify) against the now-updated branch
 * 5. Writes input folder: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 * 6. Fetches question subtasks with answers (extra context)
 * 7. Posts "Rework Started" comment to the ticket (Jira/ADO/GitHub via common/trackers.js)
 */

var configLoader = require('./configLoader.js');
var trackersModule = require('./common/trackers.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const { resolveStatuses } = require('./config.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchParentContextToInput = require('./fetchParentContextToInput.js');
var restoreFromReleases = require('./restoreFromReleases.js');
var setupCommands = require('./common/setupCommands.js');
var baseBranchMarker = require('./common/baseBranchMarker.js');

/**
 * Optionally syncs the PR's base branch with its own upstream (config.git.baseBranch)
 * before merge-conflict detection runs. Relevant in two-branch mode, where the PR's base is
 * a long-lived branch (e.g. "release/rc_*") that can drift stale relative to
 * config.git.baseBranch over time. Delegates to a project-specific hook
 * (customParams.branchSyncFnPath) because syncing may require bypassing branch-protection
 * rules that block direct pushes to that branch — same rationale as
 * customParams.branchCreateFnPath in checkoutBranch.js.
 *
 * No-op when branchSyncFnPath isn't configured, or when the PR's base already IS
 * config.git.baseBranch (nothing to sync). Failures are logged and swallowed — the sync is
 * a best-effort freshness step, not a hard prerequisite for the rest of the rework flow.
 *
 * @param {string} baseBranch    - the PR's base branch (prDetails.base.ref)
 * @param {Object} customParams  - agent customParams (may contain branchSyncFnPath)
 * @param {Object} config        - resolved project config (config.git.baseBranch, workingDir)
 */
function syncBaseBranchIfConfigured(baseBranch, customParams, config) {
    if (!customParams || !customParams.branchSyncFnPath || !baseBranch || baseBranch === config.git.baseBranch) {
        return;
    }
    var branchSyncFn = configLoader.loadHookFn(customParams.branchSyncFnPath, 'branchSyncFnPath');
    if (!branchSyncFn) {
        return;
    }
    try {
        console.log('Syncing base branch', baseBranch, 'via', customParams.branchSyncFnPath);
        branchSyncFn({
            branchName: baseBranch,
            targetBranch: config.git.baseBranch,
            workingDir: config.workingDir,
            config: config
        });
        cli_execute_command({ command: gh.buildOriginFetchCommand() });
    } catch (e) {
        console.warn('branchSyncFnPath failed (non-fatal):', e && e.toString ? e.toString() : String(e));
    }
}

// Defensive cap on Jira/tracker comment length for any failSetup() caller. The
// setupCommands module already truncates its own embedded command output at the
// source (see truncateSetupError), but other failure messages here (e.g. branch
// checkout errors) could still, in principle, be arbitrarily long — Jira rejects
// comments over ~350000 characters, and previously that rejection was silently
// swallowed, leaving the ticket with no visible failure reason at all.
var truncateForComment = setupCommands.truncateSetupError;

function failSetup(tracker, ticketKey, inputFolder, message) {
    try {
        file_write({
            path: inputFolder + '/rework_setup_failed.md',
            content: '# Rework Setup Failed\n\n' + message + '\n'
        });
    } catch (e) {
        console.warn('Failed to write rework setup failure marker:', e);
    }
    try {
        tracker.postComment(
            ticketKey,
            'h3. ❌ Rework Setup Failed\n\n' + truncateForComment(message)
        );
    } catch (e) {
        // PR-anchored reworks (#544): a 'pr-N' key parses to no tracker
        // ticket — the comment is best-effort, the failure marker file is
        // the source of truth.
        console.error('Failed to post rework setup failure comment to ' + ticketKey + ':', e && e.toString ? e.toString() : String(e));
    }
    throw new Error(message);
}

function action(params) {
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var inputFolder = actualParams.inputFolderPath;
        var ticketKey = inputFolder.split('/').pop();
        // PR-anchored rework (#544): a `pr-N` contextId makes the PR itself
        // the anchor — the labeled PR has no local issue (guest/issue-less
        // PR the owner labeled agent:rework). The PR number is taken
        // directly, no findPRForTicket body/branch scrape; tracker status
        // moves and ticket comments are skipped (a 'pr-N' key parses to no
        // GitHub issue — comments would throw).
        var anchorMatch = /^pr-(\d+)$/.exec(String(ticketKey || ''));
        var jp0 = params.jobParams || params;
        const prAnchor = (anchorMatch ? parseInt(anchorMatch[1], 10) : null) ||
            (parseInt(jp0.prNumber || jp0.pr || '', 10) || null);
        // paramsForConfigLoad re-attaches params.ticket (sibling of jobParams in the
        // real Teammate execution path) so baseBranchResolverFnPath can key off the
        // ticket's fixVersion — see configLoader.js for details.
        var config = configLoader.loadProjectConfig(configLoader.paramsForConfigLoad(params));
        var customParams = (params.jobParams && params.jobParams.customParams) || actualParams.customParams;
        var scm = configLoader.createScm(config);
        var statuses = resolveStatuses(customParams, config.jira && config.jira.statuses);
        // Probe the tracker provider once — the same script then runs unchanged
        // on Jira / ADO / GitHub deployments.
        var tracker = trackersModule.createTracker(config, customParams);

        // Restore configured artefacts (e.g. cosmo test reports) from GitHub Release — non-fatal
        try { restoreFromReleases.action(params); } catch (e) { console.warn('⚠️ restoreFromReleases failed (non-fatal):', e); }

        console.log('=== Rework setup for:', ticketKey, '===');

        // Move ticket to In Development (visible "actively being worked" marker, mirrors the
        // same transition in preCliDevelopmentSetup.js for fresh development). Opt-in only
        // (config.jira.markReworkInDevelopment) — projects whose rework bounce-back target
        // already IS an "actively being worked" status (e.g. the default IN_REWORK) don't need
        // this extra transition; enable it for projects that bounce back to a "queued" status
        // instead (e.g. READY_FOR_DEVELOPMENT) so there is still a visible marker once work starts.
        if (config.jira && config.jira.markReworkInDevelopment && !prAnchor) {
            try {
                tracker.moveToStatus(ticketKey, statuses.IN_DEVELOPMENT);
                console.log('Moved ' + ticketKey + ' to ' + statuses.IN_DEVELOPMENT);
