    // branch ref and fails when HEAD is on that branch.
    var targetedFetch = prHelper.buildTargetedOriginFetchCommand([branchName]);
    if (targetedFetch) cmd(targetedFetch);

    if (localBranchExists()) {
        cmd('git checkout ' + branchName);
