/**
 * Extracts GitHub review-thread GraphQL ids (PRRT_...) cited anywhere in a text
 * (the rework response / fix summary). Threads cited here are first-class
 * "addressed" claims — gh-692: a rework leg whose response cites thread ids but
 * whose review_replies.json lacks them used to leave the threads open forever,
 * so the threadsResolved:true re-review rule could never match (infinite loop).
 */
function extractCitedThreadIds(text) {
    var ids = [];
    var seen = {};
    String(text || '').replace(/PRRT_[A-Za-z0-9_]+/g, function(m) {
        if (!seen[m]) { seen[m] = true; ids.push(m); }
        return m;
    });
    return ids;
}

/**
 * Reads input/<ticketKey>/pr_discussions_raw.json — the thread snapshot the
 * setup action wrote BEFORE the agent ran (rootCommentId + threadId per thread).
 * Returns [] when missing/unparsable.
 */
function readInputRawThreads(ticketKey, outputOptions) {
    if (!ticketKey) return [];
    var candidates = [
        'input/' + ticketKey + '/pr_discussions_raw.json'
    ];
    var workingDir = outputOptions && outputOptions.workingDir;
    if (workingDir) candidates.push(workingDir + '/input/' + ticketKey + '/pr_discussions_raw.json');
    for (var i = 0; i < candidates.length; i++) {
        try {
            var raw = file_read({ path: candidates[i] });
            if (!raw || !raw.trim()) continue;
            var parsed = JSON.parse(raw);
            var threads = (parsed && parsed.threads) ? parsed.threads : (Array.isArray(parsed) ? parsed : []);
            if (threads && threads.length) return threads;
        } catch (e) {}
    }
    return [];
}
