                'addressed PRRT_kwDOTXdlLc6opl_v and PRRT_kwDOTXdlLc6opmBc; PRRT_kwDOTXdlLc6opl_v again'),
            ['PRRT_kwDOTXdlLc6opl_v', 'PRRT_kwDOTXdlLc6opmBc']);
        assert.deepEqual(loaded.mod.extractCitedThreadIds('no ids here'), []);
