    if (branch.indexOf(normalizedKey) !== -1) score += 80;

    if (numericPart && numericPart.length >= 3) {
        if (_containsBoundedNumber(title, numericPart)) score += 40;
        if (_containsBoundedNumber(branch, numericPart)) score += 30;
