function _switchToBranch(branchName, cmd) {
    var localBranchExists = function() {
        return cleanCommandOutput(cmd('git branch --list "' + branchName + '"') || '').trim() !== '';
    };

    // Targeted fetch of just this branch (owner rule 2026-10-03: blanket
