/**
 * Push Rework Changes Post-Action
 * postJSAction for pr_rework agent:
 * 1. Stages, commits, and pushes changes to the existing PR branch
 * 2. Posts replies to each open PR review thread and resolves the threads
 * 3. Posts the fix summary (outputs/response.md) as a top-level PR comment
 * 4. Moves ticket to "In Review"
 * 5. Posts completion comment to the ticket (Jira/ADO/GitHub via common/trackers.js)
 */

var configLoader = require('./configLoader.js');
var scmModule = require('./common/scm.js');
const commentMarkup = require('./common/commentMarkup.js');
var trackersModule = require('./common/trackers.js');
var submoduleHelper = require('./common/submodules.js');
var prHelper = require('./common/pullRequest.js');
var feedbackLoop = require('./common/feedbackLoop.js');
var autoStart = require('./common/autoStart.js');
var outputFiles = require('./common/outputFiles.js');
var gitStaging = require('./common/gitStaging.js');
const { GIT_CONFIG, STATUSES, LABELS, resolveStatuses } = require('./config.js');
var cacheToReleases = require('./cacheToReleases.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');

/**
 * Wraps feedbackLoop.resumeAgent() so an unexpected failure inside it (e.g. its own
 * mkdir/bash/run-agent.sh --continue self-invocation being blocked by a
 * misconfigured CLI_ALLOWED_COMMANDS whitelist) can never throw out of a call site.
 * Every caller treats { attempted: false } as "could not resume" and falls through to
 * posting an honest error comment / resetting the ticket — an uncaught throw here would
 * skip that fallback entirely and leave the ticket silently stuck.
 */
function tryResumeAgent(options) {
    try {
        return feedbackLoop.resumeAgent(options);
    } catch (resumeError) {
        console.error('tryResumeAgent: feedbackLoop.resumeAgent failed unexpectedly — treating as "not attempted" so the caller\'s reset/error-comment fallback still runs:', resumeError);
        return { attempted: false };
    }
}

/**
 * Returns true if the Jira ticket has the pr_approved label.
 */
function hasPrApprovedLabel(ticket) {
    var labels = (ticket && ticket.fields && ticket.fields.labels) ? ticket.fields.labels : [];
    return labels.indexOf(LABELS.PR_APPROVED) !== -1;
}

/**
 * pr_approved stickiness beats rework completion (owner rule 2026-09-21):
 * once a review concluded APPROVED, NO later rework leg may clear
 * ai_pr_reviewed or arm a re-review — the reworked head just re-validates
 * and merges. The verdict lives on the PR (REST labels: [{name}] objects
 * or strings); the ticket-hydration path (hasPrApprovedLabel) is the
 * fallback when the PR body is unavailable.
 */
function prHasApproved(pr, ticket) {
    if (pr && Array.isArray(pr.labels)) {
        for (var i = 0; i < pr.labels.length; i++) {
            var l = pr.labels[i];
            var name = (l && typeof l === 'object') ? l.name : l;
            if (name === LABELS.PR_APPROVED) return true;
        }
    }
    return hasPrApprovedLabel(ticket);
}

function normalizeLabels(singleLabel, labelList) {
    var labels = [];
    if (singleLabel) labels.push(singleLabel);
    if (Array.isArray(labelList)) {
        labelList.forEach(function(label) {
            if (label && labels.indexOf(label) === -1) labels.push(label);
        });
    }
    return labels;
}

function removeConfiguredLabels(tracker, ticketKey, customParams) {
    normalizeLabels(customParams && customParams.removeLabel, customParams && customParams.removeLabels)
        .forEach(function(label) {
            try {
                tracker.removeLabel(ticketKey, label);
                console.log('✅ Removed SM label:', label);
            } catch (e) {
                console.warn('Failed to remove SM label ' + label + ':', e);
            }
        });
}

function resolveCustomParams(params, actualParams, config) {
    var merged = {};
    var patch = configLoader.resolveInstructions(
        'pr_rework',
        null,
        config
    ).jobParamPatch;
    if (patch && patch.customParams) {
        Object.assign(merged, patch.customParams);
    }
    Object.assign(
        merged,
        (params.jobParams && params.jobParams.customParams) ||
            (actualParams && actualParams.customParams) ||
            params.customParams ||
            {}
    );
    return merged;
}

function cleanCommandOutput(output) {
    if (!output) {
        return '';
    }
    const lines = output.split('\n').filter(function(line) {
        return line.indexOf('Script started') === -1 &&
               line.indexOf('Script done') === -1 &&
               line.indexOf('COMMAND=') === -1 &&
               line.indexOf('COMMAND_EXIT_CODE=') === -1;
    });
    return lines.join('\n').trim();
}

function getGitHubRepoInfo() {
    try {
        const remoteUrl = cleanCommandOutput(
            cli_execute_command({ command: 'git config --get remote.origin.url' }) || ''
        );
        const match = remoteUrl.match(/github\.com[:/]([^/]+)\/([^/?#\s]+)/);
        if (!match) {
            return null;
        }
        return { owner: match[1], repo: match[2].replace(/\.git$/, '') };
    } catch (error) {
        console.error('Failed to get GitHub repo info:', error);
        return null;
    }
}

function findPRForTicket(scm, ticketKey) {
    try {
        const openPRs = scm.listPrs('open');

        const matching = openPRs.filter(function(pr) {
            return (pr.title && pr.title.indexOf(ticketKey) !== -1) ||
                   (pr.head && pr.head.ref && pr.head.ref.indexOf(ticketKey) !== -1);
        });

        if (matching.length > 0) {
            return matching[0];
        }

        console.warn('No open PR found for ticket', ticketKey);
        return null;
    } catch (error) {
        console.error('Failed to find PR:', error);
        return null;
    }
}

function configureGitAuthor(config) {
    try {
        cli_execute_command({ command: 'git config user.name "' + config.git.authorName + '"' });
        cli_execute_command({ command: 'git config user.email "' + config.git.authorEmail + '"' });
        return true;
    } catch (error) {
        console.error('Failed to configure git author:', error);
        return false;
    }
}

function commitAndPush(ticketKey, config, customParams) {
    var workingDir = config.workingDir || null;
    var cmdOpts = workingDir ? { workingDirectory: workingDir } : {};
    var cmd = function(command) { return cli_execute_command(Object.assign({}, cmdOpts, { command: command })); };

    // Read expected branch from pr_info.md (written by preCliReworkSetup).
    // Do NOT trust git branch --show-current — the CLI agent may have switched branches.
    var expectedBranch = null;
    try {
        var prInfoPath = 'input/' + ticketKey + '/pr_info.md';
        var prInfo = file_read({ path: prInfoPath }) || '';
        var branchMatch = prInfo.match(/\*\*Branch\*\*:\s*`([^`]+)`/);
        if (branchMatch) expectedBranch = branchMatch[1].trim();
    } catch (e) {
        throw new Error('Missing PR context file input/' + ticketKey + '/pr_info.md. Rework setup did not find or checkout a PR; refusing to commit or push.');
    }
    if (!expectedBranch) {
        throw new Error('Could not determine expected PR branch from input/' + ticketKey + '/pr_info.md; refusing to commit or push.');
    }
    var baseBranch = (config.git && config.git.baseBranch) || 'main';
    try {
        var baseMatch = prInfo.match(/\*\*Branch\*\*:\s*`[^`]+`\s*→\s*`([^`]+)`/);
        if (baseMatch && baseMatch[1]) baseBranch = baseMatch[1].trim();
    } catch (e) {}

    var currentBranch = cleanCommandOutput(cmd('git branch --show-current') || '');
    console.log('Current branch:', currentBranch, '| Expected:', expectedBranch);

    var branchName = currentBranch;
    if (expectedBranch && currentBranch !== expectedBranch) {
        console.warn('⚠️ Branch mismatch — forcing checkout to expected branch:', expectedBranch);
        try {
            cmd('git checkout ' + expectedBranch);
            branchName = expectedBranch;
            console.log('✅ Switched to expected branch:', branchName);
        } catch (e) {
            console…

/**
 * SCM (Source Control Management) abstraction layer.
 *
 * Factory: createScm(config) -> provider
 * Default provider: 'github'
 *
 * Configure globally via .dmtools/config.js:
 *   module.exports = {
 *     scm: { provider: 'ado' }, // 'github' | 'gitlab' | 'ado'
 *     repository: { owner: 'MyOrg', repo: 'my-repo' }
 *   }
 *
 * Per-agent override via JSON customParams:
 *   { "customParams": { "scmProvider": "gitlab", "targetRepository": { "owner": "MyOrg", "repo": "my-repo" } } }
 */

function _parseJson(raw) {
    if (typeof raw === 'string') {
        try { return JSON.parse(raw); } catch (e) { return raw; }
    }
    return raw;
}

function _toArray(raw) {
    var parsed = _parseJson(raw);
    if (Array.isArray(parsed)) return parsed;
    if (parsed && parsed.value) return parsed.value;
    if (parsed && parsed.workflow_runs) return parsed.workflow_runs;
    if (parsed && parsed.runs) return parsed.runs;
    return parsed ? [parsed] : [];
}

function _readFileMaybe(path) {
    try {
        var raw = file_read({ path: path });
        if (raw && raw.trim()) return raw;
    } catch (e) {
        try {
            raw = file_read(path);
            if (raw && raw.trim()) return raw;
        } catch (ignored) {}
    }
    return null;
}

function _cleanCommandOutput(output) {
    if (!output) return '';
    return output.split('\n').filter(function(line) {
        return line.indexOf('Script started') === -1 &&
               line.indexOf('Script done') === -1 &&
               line.indexOf('COMMAND=') === -1 &&
               line.indexOf('COMMAND_EXIT_CODE=') === -1;
    }).join('\n').trim();
}

function _looksLikeJavaObjectString(value) {
    return typeof value === 'string' && /^[A-Za-z0-9_.$]+@[0-9a-f]+$/.test(value.trim());
}

function _isUsableDiff(value) {
    return typeof value === 'string' && value.indexOf('diff --git') !== -1 && !_looksLikeJavaObjectString(value);
}

function _extractDiffFromToolResult(raw) {
    if (typeof raw !== 'string') {
        return raw;
    }
    // Some DMTools versions wrap the diff in a JSON envelope like {"result": "diff ..."}
    // or serialize an IBody lambda as {"arg$1": "diff ..."}. Unwrap those first.
    var trimmed = raw.trim();
    if (trimmed.charAt(0) === '{' || trimmed.charAt(0) === '[') {
        try {
            var parsed = JSON.parse(raw);
            var candidates = [parsed.result, parsed['arg$1'], parsed.body, parsed.diff];
            for (var i = 0; i < candidates.length; i++) {
                var candidate = candidates[i];
                if (typeof candidate === 'string' && _isUsableDiff(candidate)) {
                    return candidate;
                }
            }
        } catch (e) {
            // Not valid JSON — fall through to raw diff check
        }
    }
    if (_isUsableDiff(raw)) {
        return raw;
    }
    return raw;
}

function _runGitDiff(baseRef, headRef, workingDir) {
    var variants = [
        'git diff ' + baseRef + '...' + headRef,
        'git diff origin/' + baseRef + '...' + headRef,
        'git diff origin/' + baseRef + '...origin/' + headRef
    ];
    var cmdOpts = workingDir ? { workingDirectory: workingDir } : {};
    for (var i = 0; i < variants.length; i++) {
        try {
            var raw = cli_execute_command(Object.assign({}, cmdOpts, { command: variants[i] })) || '';
            var cleaned = _cleanCommandOutput(raw);
            if (_isUsableDiff(cleaned)) {
                console.log('Generated local git diff using: ' + variants[i] + ' (' + cleaned.length + ' chars)');
                return cleaned;
            }
        } catch (e) {
            console.warn('Git diff variant failed (' + variants[i] + '):', e.message || e);
        }
    }
    return '';
}

/**
 * Normalize a legacy GitHub commit-status entry (the classic pre-Checks-API
 * `/commits/{sha}/statuses` endpoint, still used by external CI systems such as Jenkins
 * that report build results via the Status API instead of GitHub Check Runs) into the same
 * shape detectFailedChecks() expects from github_get_commit_check_runs: { name, conclusion, details_url }.
 */
function _normalizeGithubCommitStatus(status) {
    var s = String((status && status.state) || '').toLowerCase();
    var conclusion = (s === 'failure' || s === 'error') ? 'failure'
        : (s === 'success') ? 'success'
        : s; // pending passes through and is filtered out by detectFailedChecks
    return {
        name: (status && status.context) || 'unknown',
        conclusion: conclusion,
        details_url: (status && status.target_url) || null
    };
}

/**
 * Fetch legacy commit statuses for a GitHub commit. No dedicated MCP tool exists for the
 * classic Status API, so this shells out via `gh api` (same established pattern as
 * updateBranch() below) and keeps only the most recent report per context — GitHub returns
 * statuses newest-first, so the first occurrence per context wins.
 */
function _getLegacyGithubCommitStatuses(workspace, repository, sha) {
    try {
        var raw = cli_execute_command({
            command: 'gh api repos/' + workspace + '/' + repository + '/commits/' + sha + '/statuses --paginate'
        }) || '';
        var cleaned = _cleanCommandOutput(raw);
        if (!cleaned) return [];
        var statuses = JSON.parse(cleaned);
        if (!Array.isArray(statuses)) return [];
        var seenContexts = {};
        var latest = [];
        for (var i = 0; i < statuses.length; i++) {
            var ctx = statuses[i].context || 'unknown';
            if (seenContexts[ctx]) continue;
            seenContexts[ctx] = true;
            latest.push(statuses[i]);
        }
        return latest;
    } catch (e) {
        console.warn('SCM GitHub: failed to fetch legacy commit statuses for', sha, ':', e.message || e);
        return [];
    }
}

/**
 * Unwrap the raw github_get_commit_check_runs() response into a plain array, tolerating the
 * various envelopes DMTools builds have used ({"result": ...}, {"check_runs": [...]}, a raw
 * array, or a single object).
 */
function _unwrapGithubCheckRuns(raw) {
    var parsed = _parseJson(raw);
    if (parsed && typeof parsed.result !== 'undefined') {
        parsed = _parseJson(parsed.result);
    }
    if (Array.isArray(parsed)) return parsed;
    if (parsed && Array.isArray(parsed.check_runs)) return parsed.check_runs;
    return parsed ? [parsed] : [];
}

function _createGithubProvider(workspace, repository) {
    return {
        listPrs: function(state) {
            return github_list_prs({ workspace: workspace, repository: repository, state: state });
        },
        getPr: function(prId) {
            return github_get_pr({ workspace: workspace, repository: repository, pullRequestId: String(prId) });
        },
        getPrComments: function(prId) {
            return github_get_pr_comments({ workspace: workspace, repository: repository, pullRequestId: String(prId) });
        },
        // Raw unified diff text via the PR API — works even after the PR is merged and
        // its head branch deleted (unlike a local `git diff <head>..<base>`).
        // Requires IS_READ_PULL_REQUEST_DIFF to be enabled; returns null on failure so
        // callers can fall back gracefully.
        getDiffText: function(prId) {
            try {
                return github_get_pr_diff_text({ workspace: workspace, repository: repository, pullRequestID: String(prId) });
            } catch (e) {
                console.warn('getDiffText (github) failed:', e && e.toString ? e.toString() : String(e));
                return null;
            }
        },
        addComment: function(prId, text) {
            return github_add_pr_comment({ workspace: workspace, repository: repository, pullRequestId: String(prId), text: text });
        },
        replyToThread: function(prId, thread, text) {
            if (thread.rootCommentId) {
                return github_reply_to_pr_thread({
                    workspace: workspace, repository: repository,
                    pullRequestId: String(prId), inReplyToId: String(thread.rootCommentId), text: text
                });
            }
