            try {
                cmd(prHelper.buildOriginFetchCommand(branchName + ':' + branchName));
            } catch (e) {
                cmd(prHelper.buildOriginFetchCommand(branchName));
            }

            if (localBranchExists()) {
                cmd('git checkout ' + branchName);
            } else {
                try {
                    cmd('git checkout -b ' + branchName + ' origin/' + branchName);
                } catch (e) {
                    if (!localBranchExists()) {
